    const bootstrapSkill = agentConfig.bootstrapSkill === undefined
        ? undefined
        : (skillSelectorSnapshot.definitions.find((skill) => skill.ownerAgentId === childAgentId && skill.shortName === agentConfig.bootstrapSkill) ?? skillSelectorSnapshot.definitions.find((skill) => skill.id === agentConfig.bootstrapSkill))
            ?.id;
    if (agentConfig.bootstrapSkill !== undefined && bootstrapSkill === undefined) {
        throw CONFIG_INVALID.create({ detail: "Configured startup skill is not authorized" });
    }
    const toolNames = resolveHostedChildToolNames(agentConfig, skillSelectorSnapshot);
    // The skill catalog and the load_skill fork guidance both advertise the
    // loader, so they must track its effective availability: an undefined
    // selector (`tools: true`) exposes it unless explicitly denied, and a
    // concrete selector exposes it only when it survived denial filtering.
    const skillLoaderExposed = toolNames === undefined
        ? agentConfig.deniedTools?.some(isLoadSkillToolName) !== true
        : toolNames.some(isLoadSkillToolName);
